import ground as G
L='spdfg'
def cfg(Z):
    d={}
    for n,l,k in G.expand(Z): d[(n,l)]=d.get((n,l),0)+k
    return d
for Z in [27,28]+list(range(57,72)):
    a,b=cfg(Z-1),cfg(Z)
    gain=[(f'{n}{L[l]}',b[(n,l)]-a.get((n,l),0)) for (n,l) in b if b[(n,l)]>a.get((n,l),0)]
    loss=[(f'{n}{L[l]}',a[k]-b.get(k,0)) for k in a if a[k]>b.get(k,0)]
    outer={f'{n}{L[l]}':k for (n,l),k in b.items() if n>=4 and (n,l) not in [(4,0),(4,1)]}
    print(Z,outer,'gain',gain,'loss',loss)"

